    "description": "根据尼泊尔警方公布的最新数据，截至当地时间29日早6时，尼泊尔北部地区山洪造成的死亡人数升至616人。 26日，尼泊尔北部热索瓦地区暴发山洪。尼泊尔政府26日决定，依据相关法律规定，将受灾地区的一些地方行政单位划为灾害危机地区，期限3个月，以便集中调配救援资源、加强人员管控和推进灾后恢复工作。",
