    "description": "新华社加拉加斯8月28日电（记者田睿）委内瑞拉代总统德尔西·罗德里格斯28日称，该国同美国达成大规模石油合作协议。 罗德里格斯通过其社交媒体发布政府公报表示，该协议将允许私营企业参与，从而大幅提高石油产量。协议提到将开发17个战略油田，投资额超过1000亿美元，并将为委内瑞拉政府带来超过2090亿美元的税收收入。 美国总统特朗普28日在社交媒体发文宣布，美国已与委内瑞拉达成协议，获得对委内瑞拉已探明石油储量中逾650亿桶的“多数控制权”…",
    "content": "新华社加拉加斯8月28日电（记者田睿）委内瑞拉代总统德尔西·罗德里格斯28日称，该国同美国达成大规模石油合作协议。 罗德里格斯通过其社交媒体发布政府公报表示，该协议将允许私营企业参与，从而大幅提高石油产量。协议提到将开发17个战略油田，投资额超过1000亿美元，并将为委内瑞拉政府带来超过2090亿美元的税收收入。 美国总统特朗普28日在社交媒体发文宣布，美国已与委内瑞拉达成协议，获得对委内瑞拉已探明石油储量中逾650亿桶的“多数控制权”。 1月29日，罗德里格斯签署了石油法改革相关法案，内容包括允许私人和外国投资委…"
