    "description": "近期，长飞光纤、亨通光电、中天科技等光纤光缆行业头部公司先后披露半年报。上半年，头部公司业绩实现高增长。其中，长飞光纤归母净利润同比增长近9倍，亨通光电实现归母净利润31.2亿元。多家公司表示，与过往由“光纤到户”或5G建设驱动的周期不同，当前在高需求的持续推动下，数据中心正取代电信运营商，成为驱动光纤行业发展的核心增长极，也推动行业迎来新一轮焕新升级。",
    "content": "近期，长飞光纤、亨通光电、中天科技等光纤光缆行业头部公司先后披露半年报。上半年，头部公司业绩实现高增长。其中，长飞光纤归母净利润同比增长近9倍，亨通光电实现归母净利润31.2亿元。多家公司表示，与过往由“光纤到户”或5G建设驱动的周期不同，当前在高需求的持续推动下，数据中心正取代电信运营商，成为驱动光纤行业发展的核心增长极，也推动行业迎来新一轮焕新升级。"
