    "content": "新华社联合国8月28日电 中国常驻联合国副代表孙磊28日在安理会海地问题公开会上发言，强调单靠军事手段无法解决海地危机。 他说，海地近日发生严重黑帮袭击，造成大量平民伤亡，中方对此深感痛心，对黑帮袭击表示强烈谴责，对受到影响的无辜海地民众深表哀悼和同情。这一袭击并非孤立事件，再次凸显了海地安全形势依然严峻，多重危机依旧难解。 孙磊指出，单靠军事手段无法解决海地危机。黑帮暴力持续蔓延只是表象，深层根源是海地长期政治动荡、治理失效、社会困顿。近期事件再次证明了依靠武力以暴制暴，反而可能开启暴力的恶性循环，给海地人民造成…"
