    "content": "据新华社报道，8月26日尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。8月28日，勘测专家团队前往西藏日喀则市吉隆县吉隆口岸上游堰塞湖区域，专业人员对堰塞湖全域开展近距离航拍作业。 2026年8月28日拍摄的日喀则市吉隆县吉隆口岸上游堰塞湖区域（无人机照片）。新华社记者 晋美多吉 摄 泥石流成因 第二次青藏科考队队长、中国科学院院士姚檀栋表示，本次区域灾害的核心诱因是冰崩灾害，冰崩发生于尼泊尔境内。从科学机理来看，这场灾害呈现典型的灾害级联效应：冰崩发生后，灾害能量顺山谷河道向下传导、…"
