    "content": "2026年08月29日 本报北京8月28日电&nbsp;&nbsp;（记者彭波）十四届全国人大常委会第七十三次委员长会议28日下午在北京人民大会堂举行。赵乐际委员长主持会议。 会议听取了全国人大宪法和法律委员会主任委员信春鹰作的关于医疗保障法草案修改稿审议情况的汇报、关于耕地保护和质量提升法草案修改稿审议情况的汇报、关于农业法修订草案修改稿审议情况的汇报、关于国防动员法修订草案修改稿审议情况的汇报、关于修改律师法的决定草案修改稿审议情况的汇报，审议了有关草案表决稿。 会议听取了全国人大常委会秘书长刘奇作的其他拟提请…"
