    "description": "2026年08月29日 新华社发 \"> 新华社记者 周 华摄 \"> 新华社发 \"> 新华社发 \"> 新华社记者 李 鹏摄 \"> 新华社发 \"> 中国共产党的优秀党员，忠诚的共产主义战士，我国民族工作和经济建设战线的杰出领导人，中国人民政治协商会议第十四届全国委员会副主席陈武同志，因病于2026年8月24日15时05分在北京逝世，享年72岁。 陈武同志，壮族，1954年11月生，广西崇左人。1972年10月参加工作，1975年2月加入中国…",
    "content": "2026年08月29日 2017年4月19日，习近平同志考察广西北海合浦汉代文化博物馆，陈武同志陪同。 新华社发 \"> 二〇〇九年八月七日，陈武同志出席在广西南宁举行的泛北部湾经济合作中方秘书处揭牌仪式。 新华社记者 周 华摄 \"> 2011年7月26日，陈武同志在国务院新闻办公室发布会上介绍中国—东盟建立对话关系20周年经贸成效及第八届中国—东盟博览会、第八届中国—东盟商务与投资峰会等方面情况。 新华社发 \"> 2014年春节前夕，陈武同志在广西都安瑶族自治县看望慰问困难群众。 新华社发 \"> 2016年10月1…"
