    "description": "2026年08月29日 7月30日，习近平总书记主持中共中央政治局会议。会议强调：“要毫不放松做好‘三农’工作，持续巩固拓展脱贫攻坚成果”“促进农民稳定增收”“抓好农业生产，夺取秋粮和全年粮食丰收”。 农为邦本，本固邦宁。今年以来，面对极端天气等挑战，我国农业农村经济交出了一份沉甸甸的答卷。夏粮产量首次突破3000亿斤，截至6月底脱贫劳动力就业规模超3200万人，上半年农村居民人均可支配收入达到12699元、同比实际增长5.5%。“十五…",
    "content": "2026年08月29日 7月30日，习近平总书记主持中共中央政治局会议。会议强调：“要毫不放松做好‘三农’工作，持续巩固拓展脱贫攻坚成果”“促进农民稳定增收”“抓好农业生产，夺取秋粮和全年粮食丰收”。 农为邦本，本固邦宁。今年以来，面对极端天气等挑战，我国农业农村经济交出了一份沉甸甸的答卷。夏粮产量首次突破3000亿斤，截至6月底脱贫劳动力就业规模超3200万人，上半年农村居民人均可支配收入达到12699元、同比实际增长5.5%。“十五五”开局之年，农业农村经济保持稳中向好的良好势头，为国民经济延续总体平稳、向新向…"
