    "content": "2026年08月29日 本报北京8月28日电&nbsp;&nbsp;（记者李心萍）近日，住房城乡建设部、自然资源部、金融监管总局联合印发《关于完善商品住房销售制度的通知》（以下简称《通知》），部署各地稳步推进商品住房销售制度改革，加快构建房地产发展新模式。 《通知》规定，各地要完善商品住房预售管理，规范商品住房预售条件。商品住房项目实行预售的，单体建筑应完成主体结构封顶。加强预售资金监管，购房人支付的首付款、个人住房贷款等购房资金应全部存入资金监管账户。《通知》施行之日前已取得建设工程规划许可证的商品住房项目，实行…"
