    "description": "2026年08月29日 本报北京8月28日电 （记者吴秋余）28日，中国人民银行、国家金融监督管理总局联合印发《关于改革完善房地产信贷管理 推动加快构建房地产发展新模式的意见》（以下简称《意见》），《意见》将个人住房贷款期限由最长30年延长至最长40年，给予借贷双方更大灵活度，具体期限由购房人与商业银行协商确定。《意见》明确，贷款期限在1年以内（含1年）的，实行到期一次性还本付息或按月还本付息；贷款期限在1年以上的，按月还本付息。《意见…",
    "content": "2026年08月29日 本报北京8月28日电&nbsp;&nbsp;（记者吴秋余）28日，中国人民银行、国家金融监督管理总局联合印发《关于改革完善房地产信贷管理&nbsp;&nbsp;推动加快构建房地产发展新模式的意见》（以下简称《意见》），《意见》将个人住房贷款期限由最长30年延长至最长40年，给予借贷双方更大灵活度，具体期限由购房人与商业银行协商确定。《意见》明确，贷款期限在1年以内（含1年）的，实行到期一次性还本付息或按月还本付息；贷款期限在1年以上的，按月还本付息。《意见》与个人住房贷款、商品住房开发贷款、…"
