    "content": "2026年08月29日 本报北京8月28日电&nbsp;&nbsp;（记者刘诗瑶）神舟二十三号航天员乘组28日圆满完成出舱活动。航天员朱杨柱时隔3年再度漫步太空，航天员张志远首次执行出舱任务。 当日13时59分，经过约5.5小时的出舱活动，神舟二十三号乘组航天员朱杨柱、张志远、黎家盈密切协同，在空间站机械臂和地面科研人员配合支持下，完成太阳翼舱外维修、空间碎片防护装置安装等任务，出舱航天员朱杨柱、张志远已安全返回天和核心舱，出舱活动取得圆满成功。 这是神舟二十三号航天员乘组首次执行出舱活动，是我国航天员第二次对太阳…"
