    "description": "2026年08月29日 本报北京8月28日电 （记者曲哲涵）财政部28日公布《中华人民共和国地方附加税法（征求意见稿）》，向社会公开征求意见。根据征求意见稿，拟将城市维护建设税、教育费附加、地方教育附加这三项税费合并为地方附加税，税率为11%—13%，具体适用税率由省、自治区、直辖市人民政府提出，报同级人大常委会决定，并报全国人大常委会和国务院备案。 根据征求意见稿，地方附加税的纳税人为在我国境内缴纳增值税、消费税的单位和个人；计税依据…",
    "content": "2026年08月29日 本报北京8月28日电&nbsp;&nbsp;（记者曲哲涵）财政部28日公布《中华人民共和国地方附加税法（征求意见稿）》，向社会公开征求意见。根据征求意见稿，拟将城市维护建设税、教育费附加、地方教育附加这三项税费合并为地方附加税，税率为11%—13%，具体适用税率由省、自治区、直辖市人民政府提出，报同级人大常委会决定，并报全国人大常委会和国务院备案。 根据征求意见稿，地方附加税的纳税人为在我国境内缴纳增值税、消费税的单位和个人；计税依据为纳税人实际缴纳的增值税、消费税税额；对进口货物或者境外单…"
