    "content": "2026年08月29日 本报南宁8月28日电&nbsp;&nbsp;（记者庞革平、张云河）28日，平陆运河顺利通过交工验收，为9月通航奠定坚实基础。 通过实地现场核查、查阅内业资料、听取各方工作汇报、集体评议讨论等规定流程，交工验收委员会一致认为：平陆运河航道线形顺直、水域尺度达标，边坡支护稳固、生态护岸绿化景观效果好，枢纽船闸及金属结构设备工程实体质量合格，且各类技术指标满足规范及设计要求，内业资料完整齐全，管理制度健全，一致同意平陆运河通过交工验收。 本次交工验收于8月27日至28日组织实施。由广西壮族自治区交…"
