    "content": "2026年08月29日 今年，第四十七届曼谷国际车展在泰国曼谷北郊印象会展中心举行。比亚迪展台前，看车、试坐和询价的消费者众多。 来自曼谷的公司职员帕妮达和丈夫带着孩子坐进比亚迪ATTO 2。“比亚迪汽车价格合适、用车成本低、售后有保障，我的朋友里也有不少人在开。”帕妮达说。 中国新能源汽车正在全球市场实力“圈粉”—— 在东南亚，泰国、新加坡等国的消费者为购得一辆中国新能源汽车热门车型，不惜长时间排队。 在欧洲，今年5月，5家中国汽车制造商在31个欧洲国家共售出13.8万辆汽车，同比增长超64%，中国车企在欧洲的月…"
