    "description": "2026年08月29日 本报上海8月28日电 （记者胡笑源）“2026中国文学盛典·鲁迅文学奖之夜”28日晚在上海举行，活动由中国作家协会、上海市人民政府主办，是鲁迅文学奖颁奖仪式首次在上海举办。 本届盛典为中篇小说、短篇小说、报告文学、诗歌、散文杂文、文学理论评论、文学翻译等7个类别共35部作品颁奖，有力呈现了中国当代文学的杰出成就，见证了文学与时代、与人民的紧密联系，为新时代文学高质量发展注入了源源不断的生机活力。 盛典现场特别设置…",
    "content": "2026年08月29日 本报上海8月28日电&nbsp;&nbsp;（记者胡笑源）“2026中国文学盛典·鲁迅文学奖之夜”28日晚在上海举行，活动由中国作家协会、上海市人民政府主办，是鲁迅文学奖颁奖仪式首次在上海举办。 本届盛典为中篇小说、短篇小说、报告文学、诗歌、散文杂文、文学理论评论、文学翻译等7个类别共35部作品颁奖，有力呈现了中国当代文学的杰出成就，见证了文学与时代、与人民的紧密联系，为新时代文学高质量发展注入了源源不断的生机活力。 盛典现场特别设置了“人民阅卷”环节，获奖作品编辑代表以及不同年龄、来自不同…"
