    "description": "2026年08月29日 暮春的风掠过川中浅丘时，我正沿318国道往蓬溪去。车窗外的田畴一层叠着一层，油菜花谢了，青麦铺得正齐，路边白色的野蔷薇、红色的三角梅开得热闹。转过一道山梁，远远就望见那座纪念碑，立在高丘之上，棱角挺拔、风骨凛然，那是徐向前元帅题写的“旷继勋牛角沟起义纪念碑”。风从那边吹过来，带着山野的清气，也仿佛带着97年前的火药味。 进沟的路叫天南路，是四川“最美农村路”之一。蜿蜒穿行在浅丘之间，扑面而来的是连片的稻田、桃林、…",
    "content": "2026年08月29日 暮春的风掠过川中浅丘时，我正沿318国道往蓬溪去。车窗外的田畴一层叠着一层，油菜花谢了，青麦铺得正齐，路边白色的野蔷薇、红色的三角梅开得热闹。转过一道山梁，远远就望见那座纪念碑，立在高丘之上，棱角挺拔、风骨凛然，那是徐向前元帅题写的“旷继勋牛角沟起义纪念碑”。风从那边吹过来，带着山野的清气，也仿佛带着97年前的火药味。 进沟的路叫天南路，是四川“最美农村路”之一。蜿蜒穿行在浅丘之间，扑面而来的是连片的稻田、桃林、青绿坡地、竹林村舍，也有红色主题的灯杆、标语牌、文化墙不时闪过。路过一片蓝莓园，…"
