    "pub_date": "2026-08-29 08:05:44",
    "author": "彭源",
    "description": "在内蒙古自治区阿拉善左旗银根苏木抵边的大漠戈壁深处，有一个特殊的“戍边夫妻警务室”。 阿拉善边境管理支队银根派出所副所长徐乃超和妻子李文娜常年驻守在这里。 夫妻二人所在的“戍边夫妻警务室”承担着3000余平方公里边境管理区、100多公里边境线的管理和治安管控工作。 作者：彭源、旷靖 新华社音视频部制作",
    "content": "在内蒙古自治区阿拉善左旗银根苏木抵边的大漠戈壁深处，有一个特殊的“戍边夫妻警务室”。 阿拉善边境管理支队银根派出所副所长徐乃超和妻子李文娜常年驻守在这里。 夫妻二人所在的“戍边夫妻警务室”承担着3000余平方公里边境管理区、100多公里边境线的管理和治安管控工作。 作者：彭源、旷靖 新华社音视频部制作"
