    "description": "“对面（尼泊尔）的地灾隐患情况我们无法查看，只能在我方一侧加装监测设施，加强监测预警。”西藏吉隆口岸遭受来自尼泊尔一侧泥石流冲击之后，西藏自治区自然资源厅一位专家表示，因信息无法同步，目前喜马拉雅山区跨境地灾隐患预警还无法实现。 8月26日10时30分许，尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。据新华社消息，截至28日15时，灾害已致我国5人遇难，558人失联。 据尼泊尔国家减少灾害风险管理局28日公…",
    "content": "“对面（尼泊尔）的地灾隐患情况我们无法查看，只能在我方一侧加装监测设施，加强监测预警。”西藏吉隆口岸遭受来自尼泊尔一侧泥石流冲击之后，西藏自治区自然资源厅一位专家表示，因信息无法同步，目前喜马拉雅山区跨境地灾隐患预警还无法实现。 8月26日10时30分许，尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。据新华社消息，截至28日15时，灾害已致我国5人遇难，558人失联。 据尼泊尔国家减少灾害风险管理局28日公布的数据，截至当地时间28日19时，尼泊尔北部地区因山洪造成的死亡人数升至579…"
