    "pub_date": "2026-08-29 07:54:08",
    "author": "刘亚南,徐静",
    "description": "新华社纽约8月28日电（记者刘亚南 徐静）美国总统特朗普28日在社交媒体发文宣布，美国已与委内瑞拉达成协议，获得对委内瑞拉已探明石油储量中逾650亿桶的“多数控制权”。 特朗普说，美委双方协作，通过与私营企业的合作，获得委内瑞拉已探明石油储量中超过650亿桶的“多数控制权”，美国纳税人无需为此承担任何费用。 特朗普称，这一交易“将使美国石油储备增加一倍以上，大幅提高石油供应，并在未来很长时间显著降低美国汽油价格”。 不过，特朗普没有披露…",
    "content": "新华社纽约8月28日电（记者刘亚南 徐静）美国总统特朗普28日在社交媒体发文宣布，美国已与委内瑞拉达成协议，获得对委内瑞拉已探明石油储量中逾650亿桶的“多数控制权”。 特朗普说，美委双方协作，通过与私营企业的合作，获得委内瑞拉已探明石油储量中超过650亿桶的“多数控制权”，美国纳税人无需为此承担任何费用。 特朗普称，这一交易“将使美国石油储备增加一倍以上，大幅提高石油供应，并在未来很长时间显著降低美国汽油价格”。 不过，特朗普没有披露该协议的具体内容，白宫尚未就此发布正式消息。 据美国阿克西奥斯新闻网站27日报道…"
