    "description": "新华社开罗8月28日电（记者张猛）喀土穆消息：苏丹民间机构和目击者28日称，该国中部北科尔多凡州北部的乌姆沙鲁地区27日遭无人机袭击，造成8名平民死亡、数十人受伤。 苏丹民间机构“紧急律师倡议”在一份声明中说，一架无人机27日上午袭击乌姆沙鲁地区一群平民，毁坏4辆民用车辆。民众实施营救、转移伤者过程中，这架无人机返回并发动第二次袭击。事发时，该地区无军事人员，也没有发生武装冲突。 目击者告诉新华社记者，袭击发生在乌姆沙鲁一处小型巴士集中…",
    "content": "新华社开罗8月28日电（记者张猛）喀土穆消息：苏丹民间机构和目击者28日称，该国中部北科尔多凡州北部的乌姆沙鲁地区27日遭无人机袭击，造成8名平民死亡、数十人受伤。 苏丹民间机构“紧急律师倡议”在一份声明中说，一架无人机27日上午袭击乌姆沙鲁地区一群平民，毁坏4辆民用车辆。民众实施营救、转移伤者过程中，这架无人机返回并发动第二次袭击。事发时，该地区无军事人员，也没有发生武装冲突。 目击者告诉新华社记者，袭击发生在乌姆沙鲁一处小型巴士集中停靠点，当时多名平民乘车等待出行。伤者已被送往医院接受治疗，一些人伤势严重。当地…"
