    "content": "新华社贝鲁特8月28日电（记者申峰 曹昌浩）黎巴嫩真主党领导人纳伊姆·卡西姆28日呼吁黎巴嫩政府取消黎以美三方框架协议，称该协议损害黎巴嫩主权，未能保障黎方权益。 据黎巴嫩真主党旗下灯塔电视台报道，卡西姆当天在黎首都贝鲁特南郊举行的一场活动上发表讲话，称该协议“不合法、不正当且具有羞辱性”。他说：“我们反对并呼吁取消该框架协议。” 卡西姆强调，真主党不希望战争，并指出真主党接受并承诺执行2024年11月27日生效的黎以停火协议。他还表示，真主党接受在联合国安理会第1701号决议框架下执行有关协议，拒绝接受超出这一框…"
