    "content": "新华社圣地亚哥8月28日电（记者朱雨博）智利、阿根廷、玻利维亚和秘鲁四国矿业主管部门官员，28日在智利首都圣地亚哥召开部长级会议并签署联合声明，呼吁加强区域合作，推动关键矿产可持续开发、技术交流与投资，共同提升该地区在全球关键矿产供应链中的地位。 联合声明强调，矿业是推动经济增长、创造就业、培养人力资本和促进社会进步的重要力量。四国将合作推动关键矿产可持续开发，围绕地质研究、矿业监管、公共政策、专业人才培养等领域加强经验交流，并探索技术和制度合作机制，鼓励公私部门共同参与科研与创新项目。 智利经济和矿业部长丹尼尔·…"
