    "content": "新华社纽约8月28日电 纽约股市三大股指28日下跌。 截至当天收盘，道琼斯工业平均指数比前一交易日下跌9.45点，收于53559.99点，跌幅为0.02%；标准普尔500种股票指数下跌19.23点，收于7711.76点，跌幅为0.25%；纳斯达克综合指数下跌138.93点，收于26402.42点，跌幅为0.52%。 板块方面，标普500指数十一大板块六跌五涨。科技板块和公用事业板块分别以1.29%和1.14%的跌幅领跌，非必需消费品板块和通信服务板块分别以1.69%和1.56%的涨幅领涨。"
