    "content": "新华社利马8月28日电（记者廖思维 王植樱）秘鲁政府28日宣布，在首都利马等地实施为期60天的紧急状态，以打击有组织犯罪及其他影响社会治安的暴力活动。 秘鲁官方媒体《秘鲁人报》当天刊载秘鲁政府发布的最高政令说，在利马大都会区及其邻近的卡亚俄地区实施紧急状态期间，秘鲁国家警察将负责维护社会治安，武装部队提供支援。警方将根据情报信息确定重点行动区域，加强巡逻、排查和身份检查，加大对非法枪支和毒品的打击力度。 近年来，秘鲁敲诈勒索、凶杀等犯罪问题突出。秘鲁内政部数据显示，今年1月至5月，利马大都会区和卡亚俄地区共登记34…"
