    "description": "新华社杭州8月28日电 题：台风“沙德尔”登陆浙江一线见闻 新华社记者王俊禄、许舜达、吴帅帅 8月28日，来势汹汹的今年第18号台风“沙德尔”，在浙江省台州玉环市坎门街道沿海、温州龙湾区沿海先后登陆。台风登陆前后，记者深入台州、温州等地台风一线，实地探访各地防风避险、坚守抗灾的现场。 3个台风接踵而至，“三碰头”考验严峻 28日上午10时许，台州玉环市坎门街道东沙社区，狂风不时裹挟着巨浪，猛烈拍击海岸护栏。被此前两次台风推倒的石柱护栏，…",
    "content": "新华社杭州8月28日电 题：台风“沙德尔”登陆浙江一线见闻 新华社记者王俊禄、许舜达、吴帅帅 8月28日，来势汹汹的今年第18号台风“沙德尔”，在浙江省台州玉环市坎门街道沿海、温州龙湾区沿海先后登陆。台风登陆前后，记者深入台州、温州等地台风一线，实地探访各地防风避险、坚守抗灾的现场。 3个台风接踵而至，“三碰头”考验严峻 28日上午10时许，台州玉环市坎门街道东沙社区，狂风不时裹挟着巨浪，猛烈拍击海岸护栏。被此前两次台风推倒的石柱护栏，已经用钢筋做了加固处理。不少沿海居民在一楼架起了防护木板，配合沙袋和挡水板。 东…"
