    "author": "李延霞",
    "description": "新华社北京8月28日电（记者李延霞）中国农业银行8月28日发布的2026年中期业绩显示，上半年，农业银行贷款新增1.69万亿元，增速6.2%；债券新增1.52万亿元，增速9.6%，含贷款、债券在内的大口径融资增量达3.2万亿元。 数据显示，今年以来，农业银行业务经营向新向优势头持续巩固，截至6月末，农业银行总资产51.06万亿元，新增2.27万亿元，增速4.7%。 服务“三农”主责主业持续夯实。截至6月末，农业银行县域贷款余额11.9万…",
    "content": "新华社北京8月28日电（记者李延霞）中国农业银行8月28日发布的2026年中期业绩显示，上半年，农业银行贷款新增1.69万亿元，增速6.2%；债券新增1.52万亿元，增速9.6%，含贷款、债券在内的大口径融资增量达3.2万亿元。 数据显示，今年以来，农业银行业务经营向新向优势头持续巩固，截至6月末，农业银行总资产51.06万亿元，新增2.27万亿元，增速4.7%。 服务“三农”主责主业持续夯实。截至6月末，农业银行县域贷款余额11.9万亿元，新增9815亿元，增速8.98%，余额占境内贷款比重进一步提升至41.9%…"
