    "content": "新华社维也纳8月28日电（记者刘海燕）据当地媒体28日报道，维也纳应用艺术博物馆27日下午发生一起持枪抢劫案，正在该馆展出的一条名贵钻石项链被盗，奥警方正对两名嫌疑人展开通缉。 据奥地利通讯社报道，两名男子于27日下午以游客身份进入这家博物馆，砸碎玻璃展柜后盗走项链，该项链是正在举办的展览中展出的珍品之一。奥媒体援引当地警方发言人报道，一名嫌疑人随身携带了一把据信为真枪的武器，并以此“开路”，另一名嫌疑人则用锤子砸碎展柜，盗走展品，二人随后逃离。 警方证实，被盗物品由巴黎珠宝商于1939年制作，铂金打造，镶嵌673…"
