    "content": "新华社南昌8月28日电（记者赖星）记者从中国铁路南昌局集团有限公司获悉，8月28日23时起，瑞金直达延安的高铁在12306铁路售票系统上开始售票，9月6日起正式开行。铁路部门依托不断完善的高铁路网优化调整运行线路，新增瑞金至延安直达高速动车。 据12306网站列车运行方案显示，瑞金至延安直达高铁车次为G3998/5/8次。列车11时02分从瑞金站始发，沿途停靠于都、赣县北、吉安西、峡江、丰城东、南昌西、共青城、庐山、瑞昌西、枫林、武汉东、漫川关、西安东等站点，22时34分抵达延安站，全程运行11小时32分钟。 据了…"
