    "content": "新华社北京8月28日电 题：唇齿相依、命运与共、相互成就——习近平主席署名文章为开创中吉关系高质量发展新局面指引方向 新华社记者 8月28日，在赴比什凯克对吉尔吉斯斯坦进行国事访问并出席2026年上海合作组织峰会前夕，国家主席习近平在《吉尔吉斯斯坦言论报》、“卡巴尔”国家通讯社发表题为《携手开创中吉关系高质量发展新局面》的署名文章。 吉尔吉斯斯坦各界人士在接受新华社记者采访时表示，习近平主席署名文章从以信相交、以利相融、以心相通、以义相守等方面，深刻阐述中吉是唇齿相依的好邻居、命运与共的好伙伴、相互成就的好朋友，为…"
